function auraMods(u){
  const out = [];
  // (the same aura from another unit is not said again where the unit's own always reaches it: an aura applies once, Core Rules 22.01;
  // two Lords of Change's Daemon Lord of Tzeentch, as one unit's copies give it once)
  const own = new Set((u.aura || []).filter(m => !m.notSelf && m.selfAlways && matches(m.needs, u)).map(m => m.from + '|' + m.note));
  for(const src of army().units) for(const m of src.aura || []){
    const self = src === u;
    if((self && m.notSelf) || !matches(m.needs, u)) continue;
    if(!self && own.has(m.from + '|' + m.note)) continue;
    out.push(Object.assign({}, m, { when:self && m.selfWhen ? m.selfWhen : m.when, src }));
  }
  return out;
}
